            final step = steps[i] as YamlMap;
            if (step['uses'] == seedAction) seedIndexes.add(i);
            final run = step['run'];
            if (run is String &&
                androidBuildSignatures.any((re) => re.hasMatch(run))) {
              buildIndexes.add(i);
            }
          }
