            setter.invoke(compileOptions, version17)
        }
    }
    tasks.configureEach {
        val kotlinOptions = extensions.findByName("kotlinOptions")
            ?: try {
                javaClass.getMethod("getKotlinOptions").invoke(this)
            } catch (_: ReflectiveOperationException) {
