{"path":"test/ci_ndk_preseed_guard_test.dart","content":"// gh-1655 rework — the ci.yml `build-android` leg went red on a transient
// truncated download inside sdkmanager: AGP resolved the app's
// `ndkVersion = flutter.ndkVersion` (28.2.13676358 for the pinned Flutter
// 3.47.x), the runner had no such NDK, so AGP invoked sdkmanager during
// `:app` configuration. sdkmanager downloaded android-ndk-r28c-linux, the
// transfer arrived truncated ("Warning: An error occurred while preparing
// SDK package NDK (Side by side) 28.2.13676358: Error on ZipFile unknown
// archive"), the exception surfaced through `evaluationDependsOn(":app")`
// (flutter_app/android/build.gradle.kts), and the leg — the aggregate
// Quality gate with it — reddened. sdkmanager's mid-configuration
// download path has NO retry; the same leg was green on the same branch
// hours earlier and on main minutes later, which is the signature of the
// download roulette, not of a code regression (the PR diff is pure Dart).
//
// The fix follows the gh-1468 doctrine exactly: pre-seed the volatile
// download BEFORE the build, through a shared composite action with
// bounded retry and a post-install verification, and pin the whole class
// with YAML-level asserts (the ci_gemma_android_seed_guard_test.dart
// static pattern — a future bare Android build job must red here, not
// silently re-enter the roulette):
//   AC1  the shared composite action exists, is composite, pre-installs
//        the Flutter-pinned NDK version with bounded retry, and verifies
//        the install on disk (source.properties Pkg.Revision) before
//        declaring success — an unverified install would send AGP into
//        its own unhardened download anyway,
//   AC2  every CI job that builds an Android APK/AAB preseeds the NDK
//        through the action BEFORE its Android build step, and
//   AC3  each workflow references the action exactly the number of times
//        the androidBuildJobs map acknowledges, and the pinned version
//        equals the ndkVersion declared by the resolved Flutter SDK's
//        gradle_utils.dart (a Flutter bump must move both sides together,
//        like the flutter_gemma seed's version+checksum cross-check); a
//        named skip line is printed when the Flutter SDK is not
//        resolvable in this environment.
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

const preseedAction = './.github/actions/android-ndk-preseed';
const actionPath = '.github/actions/android-ndk-preseed/action.yml';

/// The NDK version Flutter 3.47.x declares (`flutter.ndkVersion`, the
/// value AGP requests when the app sets `ndkVersion = flutter.ndkVersion`).
/// Must equal the `const ndkVersion` in the resolved Flutter SDK's
/// packages/flutter_tools/lib/src/android/gradle_utils.dart — AC3
/// cross-checks both sides when the SDK is resolvable; a Flutter bump
/// must move this constant and the action TOGETHER, or AGP ignores the
/// preseeded NDK and the mid-configuration download roulette returns.
const expectedNdkVersion = '28.2.13676358';

/// Every (workflow, job) that builds an Android APK/AAB for the app. The
/// gh-1468 lesson: the network-roulette fix must cover the whole class —
/// the release path (build-mobile.yml) and nightly (build-release matrix)
/// hit the same sdkmanager download the PR leg did. The disabled
/// test-android-emulator job is deliberately absent: it installs a
/// prebuilt APK artifact and never runs gradle.
const androidBuildJobs = {
  '.github/workflows/ci.yml': ['build-android'],
  '.github/workflows/build-mobile.yml': ['build-android', 'build-android-apks'],
  '.github/workflows/nightly.yml': ['build-release'],
};

/// Run-step signatures that mean "this step compiles the Android app" —
/// the preseed must run before any of them in the same job. `matrix.cmd`
/// covers nightly's build-release matrix, where the per-row command
/// (`cmd: flutter build apk --flavor store --release` on the android row)
/// is interpolated at job level.
final androidBuildSignatures = [
  RegExp(r'flutter build (apk|appbundle)\b'),
  RegExp(r'fastlane android build_release\b'),
  RegExp(r'matrix\.cmd'),
];

/// Resolves the local Flutter SDK root, or null when no SDK is
/// discoverable (FLUTTER_ROOT, then `which flutter`; the SDK root is the
/// parent of the resolved binary's bin/ directory).
String? resolveFlutterSdkRoot() {
  final envRoot = Platform.environment['FLUTTER_ROOT'];
  if (envRoot != null && Directory(envRoot).existsSync()) return envRoot;
  try {
    final which = Process.runSync('which', ['flutter']);
    if (which.exitCode != 0) return null;
    final binary = (which.stdout as String).trim();
    if (binary.isEmpty) return null;
    final real = File(binary).resolveSymbolicLinksSync();
    final root = Directory(real).parent.parent.path;
    return Directory(root).existsSync() ? root : null;
  } on IOException {
    return null;
  }
}

YamlList jobSteps(String workflowPath, String jobKey) {
  final root = loadYaml(read(workflowPath)) as YamlMap;
  final job = (root['jobs'] as YamlMap)[jobKey] as YamlMap;
  return job['steps'] as YamlList;
}

void main() {
  group('gh-1655 — Android builds preseed the Flutter-pinned NDK', () {
    test('AC1: the preseed action exists and is composite', () {
      final action = loadYaml(read(actionPath)) as YamlMap;
      expect(action['name'], isNotNull);
      final runs = action['runs'] as YamlMap;
      expect(runs['using'], 'composite');
      expect(runs['steps'], isA<YamlList>());
    });

    test('AC1: the preseed pins the NDK version, retries, and verifies',
        () {
      final body = read(actionPath);
      expect(
        body,
        contains(expectedNdkVersion),
        reason:
            'the preseed must install the exact NDK AGP requests via '
            '`ndkVersion = flutter.ndkVersion` ($expectedNdkVersion for '
            'the pinned Flutter 3.47.x) — a different version makes AGP '
            'ignore the preseeded directory and re-enter its own '
            'unhardened mid-configuration download',
      );
      expect(
        body,
        contains('--install'),
        reason: 'the preseed must go through sdkmanager --install, the '
            'same channel AGP itself uses, so the resulting tree is '
